n  //  Employment Details  set by SUPER/EXECUTIVE\n  employmentType     String?\n  employmentCategory String?\n  location           String?\n\n  //  Sensitive  only SUPER/EXECUTIVE can write these\n  salary Decimal? @db.Decimal(15, 2)\n  bonus  Decimal? @db.Decimal(15, 2)\n  equity Decimal? @db.Decimal(15, 2)\n\n  //  Relations\n  refreshTokens                          RefreshToken[]\n  auditLogs                              AuditLog[]\n  socialLinks                            AdminSocialLink[]\n  educations                             AdminEducation[]\n  documents                              AdminDocument[]\n  performanceNotes                       AdminPerformanceNote[]\n  reports                                AdminReport[]\n  sectionGrants                          AdminSectionGrant[]\n  marketingExecutionPolicyHistory        MarketingExecutionPolicyHistory[]\n  marketingExecutionValidationPackets    MarketingExecutionValidationPacket[]\n  marketingExecutionDriftAcknowledgments MarketingExecutionDriftAcknowledgment[]\n  marketingExecutionRetryReviews         MarketingExecutionRetryReview[]          @relation(\"MarketingExecutionRetryReviewer\")\n  marketingExecutionCancellationRequests MarketingExecutionJob[]                  @relation(\"MarketingExecutionCancellationRequester\")\n  marketingExecutionOverridesRequested   MarketingExecutionEmergencyOverride[]    @relation(\"MarketingExecutionOverrideRequester\")\n  marketingExecutionOverridesApproved    MarketingExecutionEmergencyOverride[]    @relation(\"MarketingExecutionOverrideApprover\")\n  marketingCampaignTeamMemberships       marketing_campaign_team_members[]        @relation(\"marketing_campaign_team_members_adminUserIdToAdminUser\")\n  marketingContentItems                  marketing_content_items[]                @relation(\"marketing_content_items_authorIdToAdminUser\")\n  socialAccountConnections               SocialAccountConnection[]\n  socialOAuthStates                      SocialOAuthState[]\n  socialPostsCreated                     SocialPost[]                             @relation(\"SocialPostCreatedBy\")\n  socialPostRevisionsCreated             SocialPostRevision[]                     @relation(\"SocialPostRevisionCreatedBy\")\n  socialApprovalsSubmitted               SocialPostApproval[]                     @relation(\"SocialApprovalSubmittedBy\")\n  socialApprovalsDecided                 SocialPostApproval[]                     @relation(\"SocialApprovalDecidedBy\")\n  socialPublicationsRequested            SocialPublication[]                      @relation(\"SocialPublicationRequestedBy\")\n  socialPublicationsApproved             SocialPublication[]                      @relation(\"SocialPublicationApprovedBy\")\n  socialMediaAssets                      SocialMediaAsset[]\n  socialContactsLinked                   SocialContact[]                          @relation(\"SocialContactLinkedBy\")\n  socialConversationsAssigned            SocialConversation[]                     @relation(\"SocialConversationAssignee\")\n  socialConversationAssignments          SocialConversation[]                     @relation(\"SocialConversationAssignedBy\")\n  socialMessagesSent                     SocialMessage[]\n  socialConversationTagsAdded            SocialConversationTag[]                  @relation(\"SocialConversationTagTaggedBy\")\n  socialCommentsAssigned                 SocialComment[]                          @relation(\"SocialCommentAssignee\")\n  socialCommentsSent                     SocialComment[]                          @relation(\"SocialCommentSentByAdmin\")\n  socialEscalationsConfirmed             SocialEscalation[]                       @relation(\"SocialEscalationConfirmedBy\")\n  socialInternalNotesAuthored            SocialInternalNote[]\n  socialSavedRepliesCreated              SocialSavedReply[]\n  socialSettingsUpdated                  SocialOperationsSetting[]\n  marketingRecommendationsAccepted       marketing_recommendations[]              @relation(\"MarketingRecommendationAcceptedBy\")\n  marketingRecommendationsDismissed      marketing_recommendations[]              @relation(\"MarketingRecommendationDismissedBy\")\n  marketingAlertsResolved                marketing_alerts[]                       @relation(\"MarketingAlertResolvedBy\")\n  marketingAlertsAcknowledged            marketing_alerts[]                       @relation(\"MarketingAlertAcknowledgedBy\")\n  marketingExperimentsCreated            marketing_experiments[]                  @relation(\"MarketingExperimentCreatedBy\")\n  marketingEvaluationRunsRequested       marketing_intelligence_evaluation_runs[] @relation(\"MarketingEvaluationRunRequestedBy\")\n  marketingSettingsUpdated               marketing_intelligence_settings[]        @relation(\"MarketingIntelligenceSettingUpdatedBy\")\n  marketingExecutionPlansCreated         MarketingExecutionPlan[]                 @relation(\"MarketingExecutionPlanCreatedBy\")\n  marketingExecutionPlansUpdated         MarketingExecutionPlan[]                 @relation(\"MarketingExecutionPlanUpdatedBy\")\n  marketingExecutionApprovals            MarketingExecutionApproval[]             @relation(\"MarketingExecutionApprovalApprover\")\n  marketingExecutionPoliciesCreated      MarketingExecutionPolicy[]               @relation(\"MarketingExecutionPolicyCreatedBy\")\n  marketingExecutionPoliciesUpdated      MarketingExecutionPolicy[]               @relation(\"MarketingExecutionPolicyUpdatedBy\")\n  marketingCreativePublicationsAuthored  MarketingCreativePublication[]           @relation(\"MarketingCreativePublicationCreatedBy\")\n  marketingDeadLetterReviews             MarketingExecutionDeadLetterReview[]     @relation(\"MarketingExecutionDeadLetterReviewer\")\n  marketingCompensationsAuthored         MarketingExecutionCompensationLink[]     @relation(\"MarketingExecutionCompensationAuthor\")\n\n  //  Work Section Relations\n  teamMemberships       TeamMember[]\n  projectMemberships    ProjectMember[]\n  assignedTasks         Task[]          @relation(\"TaskAssignee\")\n  createdTasks          Task[]          @relation(\"TaskAssigner\")\n  notifications         Notification[]\n  attendanceLogs        AttendanceLog[]\n  leaveRequests         LeaveRequest[]  @relation(\"LeaveRequestEmployee\")\n  reviewedLeaveRequests LeaveRequest[]  @relation(\"LeaveRequestReviewer\")\n  leaveBalances         LeaveBalance[]\n  payrollRecords        PayrollRecord[]\n  payslips              Payslip[]\n  deductions            Deduction[]\n  receipts              Receipt[]\n  invoices              Invoice[]\n\n  @@map(\"admin_users\")\n}\n\n// MARKETING\n\nmodel marketing_campaigns {\n  id             String                         @id(map: \"PK_marketing_campaigns\") @default(uuid())\n  title          String                         @db.VarChar(255)\n  type           marketing_campaign_type_enum\n  status         marketing_campaign_status_enum @default(Drafts)\n  description    String?\n  budget         Decimal?                       @db.Decimal(12, 2)\n  progress       Int                            @default(0)\n  launchDate     DateTime?                      @db.Date\n  estCompletion  DateTime?                      @db.Date\n  targetAudience String?\n  duration       String?                        @db.VarChar(100)\n  channels       Json?                          @db.Json\n  overview       String?\n  createdAt      DateTime                       @default(now()) @db.Timestamp(6)\n  updatedAt      DateTime                       @updatedAt @db.Timestamp(6)\n\n  performance marketing_campaign_performance?\n  timeline    marketing_campaign_timeline[]\n  team        marketing_campaign_team_members[]\n  socialPosts SocialPost[]\n\n  @@index([status], map: \"IDX_marketing_campaigns_status\")\n  @@index([type], map: \"IDX_marketing_campaigns_type\")\n  @@index([launchDate], map: \"IDX_marketing_campaigns_launchDate\")\n  @@index([createdAt], map: \"IDX_marketing_campaigns_createdAt\")\n}\n\nmodel marketing_campaign_performance {\n  id             String   @id(map: \"PK_marketing_campaign_performance\") @default(uuid())\n  campaignId     String   @unique(map: \"UQ_marketing_campaign_performance_campaignId\")\n  opens          Int      @default(0)\n  clicks         Int      @default(0)\n  conversions    Int      @default(0)\n  totalReach     Int      @default(0)\n  engagementRate Decimal  @default(0) @db.Decimal(8, 2)\n  conversionRate Decimal  @default(0) @db.Decimal(8, 2)\n  costPerClick   Decimal  @default(0) @db.Decimal(10, 2)\n  createdAt      DateTime @default(now()) @db.Timestamp(6)\n  updatedAt      DateTime @updatedAt @db.Timestamp(6)\n\n  campaign marketing_campaigns @relation(fields: [campaignId], references: [id], onDelete: Cascade, onUpdate: NoAction, map: \"FK_marketing_campaign_performance_campaignId\")\n\n  @@index([campaignId], map: \"IDX_marketing_campaign_performance_campaignId\")\n}\n\nmodel marketing_campaign_timeline {\n  id         String   @id(map: \"PK_marketing_campaign_timeline\") @default(uuid())\n  campaignId String\n  label      String   @db.VarChar(255)\n  date       DateTime @db.Date\n  done       Boolean  @default(false)\n  sortOrder  Int      @default(0)\n  createdAt  DateTime @default(now()) @db.Timestamp(6)\n  updatedAt  DateTime @updatedAt @db.Timestamp(6)\n\n  campaign marketing_campaigns @relation(fields: [campaignId], references: [id], onDelete: Cascade, onUpdate: NoAction, map: \"FK_marketing_campaign_timeline_campaignId\")\n\n  @@index([campaignId], map: \"IDX_marketing_campaign_timeline_campaignId\")\n  @@index([sortOrder, date], map: \"IDX_marketing_campaign_timeline_order\")\n}\n\nmodel marketing_campaign_team_members {\n  id          String   @id(map: \"PK_marketing_campaign_team_members\") @default(uuid())\n  campaignId  String\n  adminUserId String?\n  role        String   @db.VarChar(150)\n  createdAt   DateTime @default(now()) @db.Timestamp(6)\n  updatedAt   DateTime @updatedAt @db.Timestamp(6)\n\n  campaign  marketing_campaigns @relation(fields: [campaignId], references: [id], onDelete: Cascade, onUpdate: NoAction, map: \"FK_marketing_campaign_team_members_campaignId\")\n  adminUser AdminUser?          @relation(\"marketing_campaign_team_members_adminUserIdToAdminUser\", fields: [adminUserId], references: [id], onDelete: SetNull, onUpdate: NoAction, map: \"FK_marketing_campaign_team_members_adminUserId\")\n\n  @@index([campaignId], map: \"IDX_marketing_campaign_team_members_campaignId\")\n  @@index([adminUserId], map: \"IDX_marketing_campaign_team_members_adminUserId\")\n}\n\nmodel marketing_content_items {\n  id          String                        @id(map: \"PK_marketing_content_items\") @default(uuid())\n  title       String                        @db.VarChar(255)\n  type        String                        @db.VarChar(100)\n  authorId    String?\n  authorName  String?                       @db.VarChar(255)\n  link        String?                       @db.VarChar(1000)\n  description String?\n  status      marketing_content_status_enum @default(Draft)\n  performance Int                           @default(0)\n  createdAt   DateTime                      @default(now()) @db.Timestamp(6)\n  updatedAt   DateTime                      @updatedAt @db.Timestamp(6)\n\n  adminUser          AdminUser?                              @relation(\"marketing_content_items_authorIdToAdminUser\", fields: [authorId], references: [id], onDelete: SetNull, onUpdate: NoAction, map: \"FK_marketing_content_items_authorId\")\n  monthlyPerformance marketing_content_monthly_performance[]\n\n  @@index([status], map: \"IDX_marketing_content_items_status\")\n  @@index([authorId], map: \"IDX_marketing_content_items_authorId\")\n  @@index([updatedAt], map: \"IDX_marketing_content_items_updatedAt\")\n}\n\nmodel marketing_content_monthly_performance {\n  id        String   @id(map: \"PK_marketing_content_monthly_performance\") @default(uuid())\n  contentId String\n  month     String   @db.VarChar(20)\n  value     Int      @default(0)\n  sortOrder Int      @default(0)\n  createdAt DateTime @default(now()) @db.Timestamp(6)\n  updatedAt DateTime @updatedAt @db.Timestamp(6)\n\n  content marketing_content_items @relation(fields: [contentId], references: [id], onDelete: Cascade, onUpdate: NoAction, map: \"FK_marketing_content_monthly_performance_contentId\")\n\n  @@index([contentId], map: \"IDX_marketing_content_monthly_performance_contentId\")\n  @@index([sortOrder], map: \"IDX_marketing_content_monthly_performance_sortOrder\")\n}\n\nmodel marketing_notification_events {\n  id               String    @id(map: \"PK_marketing_notification_events\") @default(uuid())\n  eventCode        String    @unique(map: \"UQ_marketing_notification_events_eventCode\") @db.VarChar(20)\n  event            String    @db.VarChar(255)\n  notifyEnabled    Boolean   @default(true)\n  emailEnabled     Boolean   @default(true)\n  whatsappEnabled  Boolean   @default(true)\n  smsEnabled       Boolean   @default(true)\n  recipients       Json?     @db.Json\n  validToDate      DateTime? @db.Date\n  customerFullName String?   @db.VarChar(255)\n  customerEmail    String?   @db.VarChar(255)\n  customerPhone    String?   @db.VarChar(50)\n  customerCountry  String?   @db.VarChar(100)\n  emailContent     Json?     @db.Json\n  conditionalBlock Json?     @db.Json\n  whatsappContent  Json?     @db.Json\n  createdAt        DateTime  @default(now()) @db.Timestamp(6)\n  updatedAt        DateTime  @updatedAt @db.Timestamp(6)\n\n  templates marketing_email_templates[]\n\n  @@index([event], map: \"IDX_marketing_notification_events_event\")\n  @@index([validToDate], map: \"IDX_marketing_notification_events_validToDate\")\n  @@index([createdAt], map: \"IDX_marketing_notification_events_createdAt\")\n}\n\nmodel marketing_email_templates {\n  id        String   @id(map: \"PK_marketing_email_templates\") @default(uuid())\n  eventId   String\n  validFrom DateTime @db.Date\n  validTo   DateTime @db.Date\n  language  String   @db.VarChar(20)\n  status    String   @default(\"Active\") @db.VarChar(100)\n  createdAt DateTime @default(now()) @db.Timestamp(6)\n  updatedAt DateTime @updatedAt @db.Timestamp(6)\n\n  event marketing_notification_events @relation(fields: [eventId], references: [id], onDelete: Cascade, onUpdate: NoAction, map: \"FK_marketing_email_templates_eventId\")\n\n  @@index([eventId], map: \"IDX_marketing_email_templates_eventId\")\n  @@index([validTo], map: \"IDX_marketing_email_templates_validTo\")\n  @@index([createdAt], map: \"IDX_marketing_email_templates_createdAt\")\n}\n\nmodel marketing_social_accounts {\n  id                String                         @id(map: \"PK_marketing_social_accounts\") @default(uuid())\n  platform          marketing_social_platform_enum\n  username          String                         @db.VarChar(255)\n  connected         Boolean                        @default(true)\n  encryptedPassword String?\n  credentialsSaved  Boolean                        @default(false)\n  createdAt         DateTime                       @default(now()) @db.Timestamp(6)\n  updatedAt         DateTime                       @updatedAt @db.Timestamp(6)\n\n  @@unique([platform, username], map: \"UQ_marketing_social_accounts_platform_username\")\n  @@index([platform], map: \"IDX_marketing_social_accounts_platform\")\n  @@index([connected], map: \"IDX_marketing_social_accounts_connected\")\n}\n\nmodel marketing_social_posts {\n  id             String                            @id(map: \"PK_marketing_social_posts\") @default(uuid())\n  platform       marketing_social_platform_enum\n  caption        String\n  description    String?\n  excerpt        String?\n  attachmentUrl  String?                           @db.VarChar(1000)\n  attachmentUrls Json?                             @db.Json\n  thumbnailUrl   String?                           @db.VarChar(1000)\n  imageUrl       String?                           @db.VarChar(1000)\n  postedAt       DateTime?                         @db.Timestamp(6)\n  scheduledFor   DateTime?                         @db.Timestamp(6)\n  status         marketing_social_post_status_enum @default(Draft)\n  followers      Int                               @default(0)\n  views          Int                               @default(0)\n  totalLikes     Int                               @default(0)\n  comments       Int                               @default(0)\n  locations      Json?                             @db.Json\n  performance    Json?                             @db.Json\n  createdAt      DateTime                          @default(now()) @db.Timestamp(6)\n  updatedAt      DateTime                          @updatedAt @db.Timestamp(6)\n\n  @@index([platform], map: \"IDX_marketing_social_posts_platform\")\n  @@index([status], map: \"IDX_marketing_social_posts_status\")\n  @@index([postedAt], map: \"IDX_marketing_social_posts_postedAt\")\n  @@index([scheduledFor], map: \"IDX_marketing_social_posts_scheduledFor\")\n  @@index([createdAt], map: \"IDX_marketing_social_posts_createdAt\")\n}\n\nmodel marketing_social_analytics_snapshots {\n  id                    String   @id(map: \"PK_marketing_social_analytics_snapshots\") @default(uuid())\n  stats                 Json?    @db.Json\n  locations             Json?    @db.Json\n  audience              Json?    @db.Json\n  recentUpload          Json?    @db.Json\n  weeklyEngagement      Json?    @db.Json\n  totalEngagementChange String?  @db.VarChar(50)\n  createdAt             DateTime @default(now()) @db.Timestamp(6)\n  updatedAt             DateTime @updatedAt @db.Timestamp(6)\n\n  @@index([createdAt], map: \"IDX_marketing_social_analytics_snapshots_createdAt\")\n}\n\nmodel marketing_promotions {\n  id           String                          @id(map: \"PK_marketing_promotions\") @default(uuid())\n  title        String                          @db.VarChar(255)\n  discountType String                          @db.VarChar(255)\n  startDate    DateTime                        @db.Date\n  endDate      DateTime                        @db.Date\n  grossSales   Int                             @default(0)\n  averageRate  Decimal                         @default(0) @db.Decimal(8, 2)\n  grossRevenue Decimal                         @default(0) @db.Decimal(12, 2)\n  status       marketing_promotion_status_enum @default(Upcoming)\n  createdAt    DateTime                        @default(now()) @db.Timestamp(6)\n  updatedAt    DateTime                        @updatedAt @db.Timestamp(6)\n\n  @@index([status], map: \"IDX_marketing_promotions_status\")\n  @@index([startDate], map: \"IDX_marketing_promotions_startDate\")\n  @@index([endDate], map: \"IDX_marketing_promotions_endDate\")\n  @@index([createdAt], map: \"IDX_marketing_promotions_createdAt\")\n}\n\nmodel marketing_banners {\n  id                String                       @id(map: \"PK_marketing_banners\") @default(uuid())\n  mediaType         String                       @db.VarChar(100)\n  fileName          String?                      @db.VarChar(255)\n  fileUrl           String?                      @db.VarChar(1000)\n  imageUrl          String?                      @db.VarChar(1000)\n  cloudinaryId      String?                      @db.VarChar(255)\n  title             String                       @db.VarChar(255)\n  description       String\n  display           Json?                        @db.Json\n  placement         Json?                        @db.Json\n  externalLink      String                       @db.VarChar(1000)\n  startDate         DateTime                     @db.Date\n  endDate           DateTime                     @db.Date\n  status            marketing_banner_status_enum @default(Inactive)\n  totalImpressions  Int                          @default(0)\n  impressionsChange Decimal                      @default(0) @db.Decimal(8, 2)\n  clicks            Int                          @default(0)\n  clicksChange      Decimal                      @default(0) @db.Decimal(8, 2)\n  signup            Int                          @default(0)\n  signupChange      Decimal                      @default(0) @db.Decimal(8, 2)\n  createdAt         DateTime                     @default(now()) @db.Timestamp(6)\n  updatedAt         DateTime                     @updatedAt @db.Timestamp(6)\n\n  @@index([status], map: \"IDX_marketing_banners_status\")\n  @@index([startDate], map: \"IDX_marketing_banners_startDate\")\n  @@index([endDate], map: \"IDX_marketing_banners_endDate\")\n  @@index([createdAt], map: \"IDX_marketing_banners_createdAt\")\n}\n\nmodel marketing_analytics_snapshots {\n  id                   String   @id(map: \"PK_marketing_analytics_snapshots\") @default(uuid())\n  overviewStats        Json?    @db.Json\n  socialStats          Json?    @db.Json\n  adsPerformance       Json?    @db.Json\n  locations            Json?    @db.Json\n  audienceBreakdown    Json?    @db.Json\n  conversionFunnel     Json?    @db.Json\n  weeklyEngagement     Json?    @db.Json\n  performanceData      Json?    @db.Json\n  platformIntegrations Json?    @db.Json\n  createdAt            DateTime @default(now()) @db.Timestamp(6)\n  updatedAt            DateTime @updatedAt @db.Timestamp(6)\n\n  @@index([createdAt], map: \"IDX_marketing_analytics_snapshots_createdAt\")\n}\n\n// -----------------------------------------------------------------------------\n// MARKETING INTELLIGENCE (Phase 1)\n// -----------------------------------------------------------------------------\n\nmodel marketing_ad_platform_connections {\n  id                             String                                    @id(map: \"PK_marketing_ad_platform_connections\") @default(uuid())\n  platform                       marketing_ad_platform_enum\n  accountId                      String                                    @db.VarChar(255)\n  // AES-256-GCM encrypted payloads (\"v1:<iv>:<tag>:<ciphertext>\") - never plaintext\n  accessToken                    String\n  refreshToken                   String?\n  encryptedCredentials           String?\n  credentialVersion              Int                                       @default(1)\n  connectionMetadata             Json?                                     @db.Json\n  currency                       String?                                   @db.VarChar(16)\n  requiresReauthorization        Boolean                                   @default(false)\n  status                         marketing_ad_connection_status_enum       @default(ACTIVE)\n  lastSyncedAt                   DateTime?                                 @db.Timestamp(6)\n  lastSyncError                  String?\n  validationStatus               marketing_provider_validation_status_enum @default(NOT_VALIDATED)\n  lastConnectionTestAt           DateTime?                                 @db.Timestamp(6)\n  lastSuccessfulFetchAt          DateTime?                                 @db.Timestamp(6)\n  lastMetricReconciliationAt     DateTime?                                 @db.Timestamp(6)\n  lastPaginationVerificationAt   DateTime?                                 @db.Timestamp(6)\n  lastRateLimitVerificationAt    DateTime?                                 @db.Timestamp(6)\n  lastTokenRefreshVerificationAt DateTime?                                 @db.Timestamp(6)\n  sanitizedValidationError       String?\n  // Token lifecycle metadata (populated when the provider reports expiry)\n  accessTokenExpiresAt           DateTime?                                 @db.Timestamp(6)\n  refreshTokenExpiresAt          DateTime?                                 @db.Timestamp(6)\n  createdAt                      DateTime                                  @default(now()) @db.Timestamp(6)\n  updatedAt                      DateTime                                  @updatedAt @db.Timestamp(6)\n\n  rawInsights          marketing_ad_insights_raw[]\n  performanceSnapshots marketing_performance_snapshots[]\n  oauthStates          marketing_oauth_states[]\n  evaluationRuns       marketing_intelligence_evaluation_runs[]\n  creativeAssets       marketing_creative_assets[]\n  creativeSnapshots    marketing_creative_performance_snapshots[]\n  recommendations      marketing_recommendations[]\n  alerts               marketing_alerts[]\n  experiments          marketing_experiments[]\n  intelligenceSettings marketing_intelligence_settings[]\n  executionPlans       MarketingExecutionPlan[]\n  executionJobs        MarketingExecutionJob[]\n  executionPolicies    MarketingExecutionPolicy[]\n  creativePublications MarketingCreativePublication[]\n  targetingDiscoveries MarketingTargetingDiscovery[]\n  accountLocks         MarketingExecutionAccountLock[]\n  executionOverrides   MarketingExecutionEmergencyOverride[]\n\n  @@unique([platform, accountId], map: \"UQ_marketing_ad_platform_connections_platform_accountId\")\n  @@index([platform, status], map: \"IDX_marketing_ad_platform_connections_platform_status\")\n}\n\nmodel marketing_ad_insights_raw {\n  id                 String                     @id(map: \"PK_marketing_ad_insights_raw\") @default(uuid())\n  connectionId       String?\n  accountId          String                     @default(\"UNKNOWN\") @db.VarChar(255)\n  platform           marketing_ad_platform_enum\n  campaignExternalId String                     @db.VarChar(255)\n  date               DateTime                   @db.Date\n  rawJson            Json                       @db.Json\n  payloadCategory    String                     @default(\"CAMPAIGN_INSIGHT\") @db.VarChar(64)\n  payloadKey         String?                    @unique(map: \"UQ_marketing_ad_insights_raw_payloadKey\") @db.VarChar(128)\n  requestRangeStart  DateTime?                  @db.Date\n  requestRangeEnd    DateTime?                  @db.Date\n  providerRequestId  String?                    @db.VarChar(255)\n  requestMetadata    Json?                      @db.Json\n  fetchedAt          DateTime                   @default(now()) @db.Timestamp(6)\n  createdAt          DateTime                   @default(now()) @db.Timestamp(6)\n\n  connection                   marketing_ad_platform_connections?         @relation(fields: [connectionId], references: [id], onDelete: SetNull, onUpdate: NoAction, map: \"FK_marketing_ad_insights_raw_connectionId\")\n  creativePerformanceSnapshots marketing_creative_performance_snapshots[]\n\n  @@unique([platform, accountId, campaignExternalId, date], map: \"UQ_marketing_ad_insights_raw_platform_account_campaign_date\")\n  @@index([connectionId], map: \"IDX_marketing_ad_insights_raw_connectionId\")\n  @@index([platform, date], map: \"IDX_marketing_ad_insights_raw_platform_date\")\n  @@index([platform, accountId, date], map: \"IDX_marketing_ad_insights_raw_platform_account_date\")\n  @@index([campaignExternalId], map: \"IDX_marketing_ad_insights_raw_campaignExternalId\")\n}\n\nmodel marketing_performance_snapshots {\n  id                    String                     @id(map: \"PK_marketing_performance_snapshots\") @default(uuid())\n  connectionId          String?\n  accountId             String                     @default(\"UNKNOWN\") @db.VarChar(255)\n  platform              marketing_ad_platform_enum\n  campaignExternalId    String                     @db.VarChar(255)\n  campaignName          String                     @db.VarChar(512)\n  date                  DateTime                   @db.Date\n  currency              String                     @default(\"UNSPECIFIED\") @db.VarChar(16)\n  spend                 Decimal                    @default(0) @db.Decimal(14, 2)\n  impressions           Int                        @default(0)\n  clicks                Int                        @default(0)\n  signups               Int                        @default(0)\n  activeUsers           Int                        @default(0)\n  payments              Int                        @default(0)\n  refunds               Int                        @default(0)\n  chargebacks           Int               